#include "ksStateModeTask.h"
#include <iostream>
#include <vector>
#include <utility>
#include <stdexcept>
using T=ks::StateModeTask;using W=T::Write;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;auto verify=[&](unsigned mode,unsigned previousMode,unsigned parts,unsigned aux,unsigned bindActive,unsigned slotActive,unsigned compareActive,unsigned previousActive,unsigned rememberActive,unsigned program,unsigned slotProgram){T task;unsigned reads=0,clocks=0,children=0;std::vector<std::pair<W,uint32_t>> writes;auto read=[&](T::Read r)->unsigned{++reads;switch(r){case T::Read::Mode:return mode;case T::Read::PreviousMode:return previousMode;case T::Read::PartMask:return parts;case T::Read::AuxMask:return aux;case T::Read::Active:check(task.stage()==T::Stage::ReadBindActive||task.stage()==T::Stage::ReadSlotActive||task.stage()==T::Stage::ReadCompareActive||task.stage()==T::Stage::ReadRememberActive,"Active read identity differs");return task.stage()==T::Stage::ReadBindActive?bindActive:task.stage()==T::Stage::ReadSlotActive?slotActive:task.stage()==T::Stage::ReadCompareActive?compareActive:rememberActive;case T::Read::PreviousActive:return previousActive;case T::Read::CurrentProgram:return program;case T::Read::SingleSlot:case T::Read::SlotProgram:return slotProgram;}return 0;};auto write=[&](W w,uint32_t v){writes.emplace_back(w,v);};while(!task.complete()){if(task.awaitingPart()){check(task.part()==bindActive,"Mode bind part differs");++children;check(task.resumePart(),"Mode child rejected");continue;}const auto c=task.nextClocks(),before=reads;const auto stores=writes.size();check(!task.advanceBefore(c-1,read,write)&&reads==before&&writes.size()==stores,"Mode early access");check(task.advanceBefore(c,read,write)==c,"Mode admission differs");clocks+=c;}
 std::vector<std::pair<W,uint32_t>> expected;unsigned expectedReads,expectedClocks;if(!mode){expected={{W::Active,0},{W::AuxMask,1},{W::PartMask,1},{W::CurrentBase,0x168fc},{W::LiveBase,0x16e12},{W::PreviousMode,mode}};expected.emplace_back(mode==previousMode?W::SingleSlot:W::CurrentProgram,mode==previousMode?program:slotProgram);expectedReads=3;expectedClocks=292;check(children==0,"Single mode child");}else{unsigned selected=4,scan=45;for(unsigned i=0;i<3;++i)if(parts&(1u<<i)){selected=i+1;scan=15*i+6;break;}expected={{W::PartMask,parts&15},{W::Active,selected},{W::AuxMask,aux&15},{W::PreviousMode,mode}};const bool restore=mode!=previousMode||compareActive!=previousActive;if(restore){expected.emplace_back(W::CurrentProgram,slotProgram);expected.emplace_back(W::PreviousActive,rememberActive);}else expected.emplace_back(W::SlotProgram,program);expectedReads=mode!=previousMode?8:restore?10:9;expectedClocks=66+30+scan+69+57+(mode!=previousMode?42:30+(restore?42:21))+68;check(children==1&&task.slotOffset()==uint8_t(slotActive*2),"Multi mode child/byte slot wrap");}
 if(clocks!=expectedClocks){std::cerr<<"mode="<<mode<<" prev="<<previousMode<<" mask="<<parts<<" clocks="<<clocks<<" expected="<<expectedClocks<<'\n';throw std::runtime_error("Mode schedule differs");}if(reads!=expectedReads||writes!=expected){std::cerr<<"mode="<<mode<<" prev="<<previousMode<<" reads="<<reads<<" expected="<<expectedReads<<'\n';throw std::runtime_error("Mode state changes differ");}check(!task.resumePart()&&!task.advanceBefore(999,read,write),"Mode restarted");++cases;};
 for(unsigned mode=0;mode<256;++mode)for(unsigned previous=0;previous<256;++previous)for(unsigned parts:{0u,1u,2u,3u,4u,5u,8u,15u,127u,128u,255u})verify(mode,previous,parts,mode^previous,parts,mode,(mode+previous)&255,previous,mode^previous,(mode<<8)|previous,(previous<<8)|mode);
 for(unsigned parts=0;parts<256;++parts)for(unsigned aux=0;aux<256;++aux)verify(1,1,parts,aux,parts,aux,parts,parts,aux,0xdead,0xbeef);
 for(unsigned slot=0;slot<256;++slot)for(unsigned previousActive=0;previousActive<256;++previousActive)verify(255,255,slot,previousActive,slot,slot,slot,previousActive,previousActive,0x8000|slot,0xff00|previousActive);
 std::cout<<"PASS: "<<cases<<" whole mode transitions,all256mode pairs/masks/aux/lateactive/slot wrap,program preservation,typed bind,ordered memory changes and exact clocks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
